    try {
      if (id === null) {
        const added = await this.api.add(fields);
        this.people.update((list) => [...list, added]);
      } else {
        const saved = await this.api.update(id, fields);
        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
      }
